/* @socom-skeleton stub InitAiBrain__11CSealCtrlAiFv */
void CSealCtrlAi::InitAiBrain()
{
	/* 0x26a8d0 (after the vehicle entry's parameters are copied in): reset the brain. The
	 * alive valve is set, look / states / route cleared, idle mode. The player's team (bit
	 * 1) makes it a SEAL: hold-fire valve set, no fade, no snooze, the player's
	 * invincibility, team 26, and its handle from the node name (H / B / D); everyone else
	 * is an enemy with binoculars. The character type's AI parameters are merged in and
	 * seed courage, discipline, the view (fov in degrees, range, sensitivity). */
	CZSealBody* seal = static_cast<CZSealBody *>(m_entity);

	m_aware.m_value = 0.0f;
	m_aware.m_goal = 0.0f;
	CValve* alive = m_valve[2];

	if (alive != NULL)
	{
		bool changed = alive->m_value != 1;
		alive->m_value = 1;

		if (changed)
			alive->MakeCallbacks((VALVE_STATE)1);
	}

	ClearLook((AI_LOOK)-1);
	ClearAiState(true);
	SetAiState(STATE_UNKNOWN);
	Debug("ClearRoute()...\n");
	/* ELF: ClearRoute inlined - ai::AbortPathPlan(&m_path), m_path.Clear(), the default
	 * path type with bias 1.0. port: not written (the path planner is not written) */
	SetAiMode(AIM_IDLE);

	if (seal->m_team & 2)
	{
		m_navyseal = 1;

		if (m_valve[0] != NULL)
			m_valve[0]->Set(1);

		m_nofade = 1;
		m_nosnooze = 1;
		seal->m_invincible = ftsGetPlayer()->m_invincible;
		seal->JoinTeam(26);
		m_debug = 0;

		switch (toupper(seal->m_node->m_name[0]))
		{
		case 'D':
			m_handle = 3;
			break;
		case 'B':
			m_handle = 2;
			break;
		case 'H':
			m_handle = 1;
			break;
		}
	}
	else
	{
		m_navyseal = 0;

		if (m_valve[0] != NULL)
			m_valve[0]->Set(0);

		seal->m_kit.SetupBinocular();
		m_handle = 0;
		m_debug = 0;
	}

	/* the body is kept on the AI map's cells (CZSealBody::PostComputeNextPosition ->
	 * CAiMaps::GetCellRepelParams) */
	m_do_aimap_collide = 1;
	UpdateEventMask();
	CCharacterType* type = seal->GetCharacter();

	if (type != NULL)
	{
		m_aiParams.Merge(m_aiParams, type->m_aiParams);
		m_courage.m_value = m_aiParams.courage;
		m_courage.m_goal = m_aiParams.courage;
		m_dicipline.m_value = m_aiParams.target_discipline;
		m_dicipline.m_goal = m_aiParams.target_discipline;
		SetViewFOV(0.01745329f * m_aiParams.visual_fov);
		SetViewRange(m_aiParams.visual_range);
		m_vissens.m_value = m_aiParams.visual_sens;
		m_vissens.m_goal = m_aiParams.visual_sens;
	}

	if (seal->m_team & 0x10000000)
		seal->m_restrainable = 1;

	/* ELF: team bit 0x20000 (hostages): restrained from the start in a network game
	 * (STATE_RESTRAINED, unit 17), an "ESCORTEE" compass anchor. port: not written */

	if (m_has_respawned)
	{
		OnMissionStart();
		/* ELF: a STATE_SCRIPT top state runs its "on_respawn" sequence. port: not written
		 * (CAiSScript) */
	}

#ifdef SOCOM_PORT
	SOCOM_PORT_TRACE("AI: %s brain: %s range %d fov %d sens %d%% acc %d%% courage %d%% delay %d ms", seal->m_node->m_name,
		m_navyseal ? "seal" : "enemy", (int)m_visrange.m_value, (int)m_aiParams.visual_fov, (int)(m_vissens.m_value * 100.0f),
		(int)(m_aiParams.accuracy * 100.0f), (int)(m_aiParams.courage * 100.0f), (int)(m_aiParams.target_delay * 1000.0f));
#endif
}

/* @socom-skeleton stub CreateAiEvent__9CSealCtrlFQ28CAiEvent5EVENTffbPC6CPnt3DUi */
bool CSealCtrl::CreateAiEvent(CAiEvent::EVENT event, float duration, float radius, bool visible, const CPnt3D *pos, unsigned int userdata)
{
	/* 0x26a760 (OnWeaponEvent): an event from this seal (at pos, else its own position), no
	 * sooner after the last of that type than the type's rate (on the mission clock) */
	f32 *last = &m_event_time[(s8)event];
	f32 now = theMission.m_timer;

	if (now - *last <= CAiEvent::GetEventRate(event))
		return false;

	*last = now;
	CEntity *body = m_entity;
	CAiEvent *ev = CAiEvent::Acquire();
	ev->m_type = (s8)event;
	ev->m_duration = duration;
	ev->m_rangeSq = radius * radius;
	ev->m_visible = visible ? 1 : 0;
	ev->m_pos = pos != NULL ? *pos : *body->GetPosW();
	ev->m_userdata = userdata;
	ev->m_owner = body->m_id;
	CAiEvent::Create(ev);
	return true;
}

/* @socom-skeleton stub UpdateEventMask__11CSealCtrlAiFv */
void CSealCtrlAi::UpdateEventMask()
{
	/* 0x26a5b0 (InitAiBrain, SetSleeping, ai::TEAM): which event types the AI hears. A
	 * sleeping or snoozing AI (or team bit 0x4000000) ignores types 0-4, 6, 7 and 10-14
	 * (it hears only WEPHIT, WEPFIRE and EXPLOSION); hostages (team 0x10000000 or 0x20000)
	 * ignore 0-4, 6 and 12-14; SEALs (team 2) ignore UNKNOWN and GENERIC; nothing is heard
	 * in a network game */
	/* @socom-skeleton stub sleeper_ignore$2774 */
	static u32 sleeper_ignore = CAiEvent::MakeMaskEx(CAiEvent::AIE_UNKNOWN, 1, 2, 3, 4, 6, 7, 10, 11, 12, 13, 14, -1);
	/* @socom-skeleton stub hostage_ignore$2777 */
	static u32 hostage_ignore = CAiEvent::MakeMaskEx(CAiEvent::AIE_UNKNOWN, 1, 2, 3, 4, 6, 12, 13, 14, -1);
	/* @socom-skeleton stub navyseal_ignore$2780 */
	static u32 navyseal_ignore = CAiEvent::MakeMaskEx(CAiEvent::AIE_UNKNOWN, 1, -1);
	CEntity *body = m_entity;
	m_eventMask = (u32)-1;

	if ((m_snoozing || m_sleeping) || (body->m_team & 0x4000000))
		m_eventMask &= ~sleeper_ignore;

	if ((body->m_team & 0x10000000) || (body->m_team & 0x20000))
		m_eventMask &= ~hostage_ignore;

	if (body->m_team & 2)
		m_eventMask &= ~navyseal_ignore;

	if (theNetwork.m_bNetwork)
		m_eventMask = 0;
}

/* @socom-skeleton stub OnWeaponEvent__11CSealCtrlAiFP12CZProjectileUiPv */
void CSealCtrlAi::OnWeaponEvent(CZProjectile *projectile, unsigned int, void *)
{
	/* 0x26a290 (CZSealBody::HandleWeaponEvent: a projectile flew this frame, weapon event 1).
	 * An awake, living AI measures how close the projectile's frame segment passed: an enemy's
	 * shot by the player within player_threshold makes the player call for help (HELPATTACK
	 * event, 0.5 s, range 1500, carrying this AI's id); any enemy shot within thip_range opens
	 * the shot-at valve, adds underfire (underfire_thip_delta, more the closer), keeps where it
	 * came from and who fired, and raises the awareness to just under AIA_SPECIFIC (a POINT
	 * event at the shot while below it: SetAiAware(AIA_DIRECTION) inlined). ELF: helpattack_range is set but not read here. */
	/* @socom-skeleton stub player_threshold$2799 */
	static float player_threshold = 70.0f;
	/* @socom-skeleton stub helpattack_range$2802 */
	static float helpattack_range = 300.0f; /* port: float, as the ELF's word (0x43960000) */
	(void)helpattack_range;
	CEntity *body = m_entity;

	if (m_snoozing || m_sleeping || !body->m_isAlive)
		return;

	const CPnt3D *pos = body->GetPosW();
	const CPnt3D *from = &projectile->m_framestartpos;
	f32 dist = 999999.0f;
	CEntity *shooter = CEntity::m_list.GetEntityById(projectile->m_shooterID);
	bool enemy = shooter != NULL && (shooter->m_team & body->m_team) == 0;
	u32 shooter_id = projectile->m_shooterID;
	CZSealBody *player = ftsGetPlayer();

	if (!enemy)
		return;

	if (!pos->DistToVector(from, &projectile->m_frameendpos, &dist))
		return;

	if (dist < player_threshold && shooter_id == player->m_id)
		static_cast<CSealCtrl *>(player->m_control)->CreateAiEvent(CAiEvent::AIE_HELPATTACK, 0.5f, 1500.0f, false, player->GetPosW(), body->m_id);

	if (!(dist < m_aiParams.thip_range))
		return;

	SetValve((SEAL_VALVE)1, 2);
	m_underfire.m_value += ai::underfire_thip_delta * (1.0f - dist / m_aiParams.thip_range);
#ifdef SOCOM_PORT
	SOCOM_PORT_TRACE("AI: %s: a round passed %.1f away: underfire %.2f", body->m_node->m_name, (double)dist, (double)m_underfire.m_value);
#endif
	m_underfire_pos = *from;
	m_underfire_shooter = shooter;

	SetAiAware(AIA_DIRECTION, from); /* inlined in the ELF */
}

/* @socom-skeleton stub OnWeaponHit__11CSealCtrlAiFPQ23zdb15IntersectStructP12CZProjectile */
void CSealCtrlAi::OnWeaponHit(zdb::IntersectStruct *, CZProjectile *projectile)
{
	/* 0x26a0a0 (CZSealBody::OnWeaponHit, before the damage): the shooter (the seal of the
	 * projectile's owner node) is marked hostile in this body's target list and its position
	 * kept; without one the position is -100 x the projectile's velocity (ELF quirk kept: not
	 * offset by anything). Unless the shooter is the current target the position gets event
	 * noise and the awareness rises as for a passing shot. Underfire grows by
	 * underfire_hit_delta, the shot's position and shooter are kept, the shot-at valve opens. */
	CZSealBody *shooter = CZSealBody::GetSeal(projectile->m_owner);
	CPnt3D pos;

	if (shooter != NULL)
	{
		Debug("OnWeaponHit() *** SHOT BY: [%s] projectile=0x%08x\n", shooter->m_node->m_name, (u32)(uintptr_t)projectile);
		CTarget *t = m_entity->m_targets.FindTarget(shooter);
		pos = *shooter->GetPosW();

		if (t != NULL)
			t->m_hostile = 1;
	}
	else
	{
		projectile->m_vel.Scale(-100.0f, &pos);
	}

	if (m_target.m_target.m_ent != shooter)
	{
		PNT2D noise;
		memcpy(&noise, ai::eventNoise, sizeof(noise));
		ai::AddNoise(&pos, noise);
		SetAiAware(AIA_DIRECTION, &pos); /* inlined in the ELF */
	}

	m_underfire.m_value += ai::underfire_hit_delta;
	m_underfire_pos = pos;
	m_underfire_shooter = shooter;
	SetValve((SEAL_VALVE)1, 2);
}

/* @socom-skeleton stub OnStunDamage__11CSealCtrlAiF9STUN_TYPEfPC6CPnt3D */
void CSealCtrlAi::OnStunDamage(STUN_TYPE type, float amount, const CPnt3D *from)
{
	/* 0x269c00: an enemy hit by a stun (CZSealBody::HandleStunDamage) loses sight range,
	 * discipline, hearing and courage by type and gets STATE_STUNNED with a reaction anim:
	 * flashbang - a cower (stand / crouch: one of two at random; prone: ProneCover) when the
	 * head faces away from the blast or it went off within 15, else no anim; tear gas -
	 * Cough_stagger, smoke - Cough, both coughing (SND_COUGH every 0.15-0.4 s); explosion -
	 * hearing only. A SEAL, or an AI already stunned, only gets the stun's duration again
	 * (m_time). A grenade throw being set up is dropped. */
	CAiState *top = GetAiState();

	if (!m_navyseal && (top == NULL || top->m_state != STATE_STUNNED))
	{
		f32 dot = 1.0f;
		f32 dist = 0.0f;
		u32 t = (u8)type;

		if (from != NULL)
		{
			CPnt3D head, dir, d;
			static_cast<CZSealBody *>(m_entity)->GetHeadParams(&head, &dir);
			head.Sub(from, &d);
			dist = d.Normalize();
			dot = d.x * dir.x + d.y * dir.y + d.z * dir.z;
		}

		CSnd *sound = NULL;
		s16 anim = -1;

		switch (t)
		{
		case 0:
			m_visrange.m_value *= 0.1f;
			m_dicipline.m_value *= 0.6f;
			m_audiofactor.m_value = 0.0f;
			m_courage.m_value *= 0.5f;

			if (dot <= 0.0f && !(dist <= 15.0f))
				break;
			{
				bool first = (f32)rand() * 4.656613e-10f * 1.0f + 0.0f <= 0.5f;

				if (m_stance == 0)
					anim = (s16)FindAnimType(first ? "Flashbang cower" : "Flashbang cower2");
				else if (m_stance == 1)
					anim = (s16)FindAnimType(first ? "Crouch flashbang cower" : "Crouch flashbang cower2");
				else if (m_stance == 2)
					anim = AnimTypes::ProneCover;
			}
			break;

		case 1:
			m_visrange.m_value *= 0.1f;
			m_dicipline.m_value *= 0.6f;
			anim = (s16)FindAnimType("Cough_stagger");
			sound = CSnd::GetSoundByName("SND_COUGH");
			break;

		case 3:
			m_dicipline.m_value *= 0.6f;
			anim = (s16)FindAnimType("Cough");
			sound = CSnd::GetSoundByName("SND_COUGH");
			break;

		case 4:
			m_audiofactor.m_value *= 0.1f;
			break;

		default:
			break;
		}

		if (GetAiState()->m_state == STATE_GRENADE)
			GetAiState()->m_setup = 0;

#ifdef SOCOM_PORT
		SOCOM_PORT_TRACE("AI: %s: stunned (type %d, %.2f, dist %.0f, dot %.2f): anim %d", m_entity->m_node->m_name, (int)t, amount, dist, dot, (int)anim);
#endif

		if (PushAiState(STATE_STUNNED, true))
		{
			CAiState *now = GetAiState();
			CAiSStunResponse *st = now->m_state == STATE_STUNNED ? static_cast<CAiSStunResponse *>(now) : NULL; /* ELF: NULL is written through */
			st->m_time = amount;
			st->m_type = t;
			st->m_anim = anim;
			st->m_cough_period.m_min = 0.15f;
			st->m_cough_period.m_range = 0.25f;
			st->m_sound = sound;
			st->m_setup = 1;
		}

		return;
	}

	top = GetAiState();

	if (top->m_state == STATE_STUNNED && top->m_setup)
		top->m_time = amount;
}

