/* @socom-skeleton stub PostMortemPreTick__11CSealCtrlAiFf */
void CSealCtrlAi::PostMortemPreTick(float dT)
{
	/* 0x267b30 (CZSealBody::PreTick while dead): a dead AI's body goes away. Never with
	 * m_nofade. Without respawns left: once its node is active and it has stayed out of the
	 * camera entity's view cone and farther than the mission's recycle range for
	 * recycle_time seconds (the timer counts down while it is seen or near), the node is
	 * hidden, its AI event loses its type and the mission recycles the entity (CMission::
	 * RecycleEntity: a waiting recycle entry spawns in its slot). With respawns left: after
	 * respawn_time the body fades out (0.75 a second); a hidden one asks for a respawn
	 * (CZSealBody::DoRespawn) and uses one up. ELF: returns 1 (port: void, as the base). */
	CEntity *body = m_entity;
	zdb::CNode *node = body->GetNode();
	bool active = node->m_active != 0;

	if (m_nofade)
		return;

	if (m_aiParams.respawn != 0)
	{
		m_recycleTimer += dT;

		if (!active)
		{
			static_cast<CZSealBody *>(body)->m_needs_respawn = true;
			m_aiParams.respawn--;
			return;
		}

		if (m_recycleTimer < theMission.m_ai_params.respawn_time)
			return;

		f32 opacity = node->m_Opacity;

		if (opacity != 0.0f)
		{
			f32 step = 0.75f * dT;

			/* _saturate<f>: 0..1 when fading out, 0..0 for a negative opacity */
			if (0.0f <= opacity)
			{
				opacity -= step;
				opacity = opacity < 0.0f ? 0.0f : (opacity > 1.0f ? 1.0f : opacity);
			}
			else
			{
				opacity += step;
				opacity = opacity < 0.0f ? 0.0f : (opacity > 0.0f ? 0.0f : opacity);
			}

			node->m_Opacity = opacity;
		}

		node->SetActive(opacity != 0.0f);
		return;
	}

	if (!active)
		return;

	bool recycle = true;
	CEntity *viewer = appCamera->m_entity;

	if (viewer != NULL)
	{
		CPnt3D pos;
		body->GetTargetPosW(&pos);
		CAiCone *cone = &static_cast<CSealCtrl *>(viewer->m_control)->m_view_cone;
		bool seen = cone->ContainsPoint(&cone->m_cone_pos, &cone->m_cone_dir, &pos);

		if (!seen)
		{
			CPnt3D d;
			body->GetPosW()->Sub(viewer->GetPosW(), &d);

			if (d.x * d.x + d.y * d.y + d.z * d.z < theMission.m_ai_params.recycle_range)
				seen = true;
		}

		if (!seen)
			m_recycleTimer += dT;
		else if (!(m_recycleTimer <= dT))
			m_recycleTimer -= dT;

		recycle = !(m_recycleTimer < theMission.m_ai_params.recycle_time);
	}

	if (!recycle)
		return;

	node->SetActive(false);
	CAiEvent *event = static_cast<CZSealBody *>(body)->m_aiEvent;

	if (event != NULL)
		event->m_type = 0;

	theMission.RecycleEntity(body);
}

/* @socom-skeleton stub PreTick__11CSealCtrlAiFf */
bool CSealCtrlAi::PreTick(float dT)
{
	/* 0x2675e0 (CZSealBody::PreTick): the AI's frame. A sleeping or snoozing AI only
	 * counts itself and ticks its events. An awake one: target upkeep, view cone, sensors
	 * (which run the attack), the state stack, then the movement mode's tick; the throttles
	 * ramp to their goals (accelRate when growing, decelRate when shrinking) and the
	 * shot-at valve counts down. Returns whether the body runs its post tick. */
	/* @socom-skeleton stub logFrameNum$3101 */
	static long logFrameNum = -1;

	_dT = dT;
	_dTI = dT <= 0.0f ? 0.0f : 1.0f / dT;
	/* ELF: with aiLogEnabled a frame record (type 0) is written to the AI log once per
	 * frame (logFrameNum). port: not written (CAiLog) */
	CZSealBody* seal = static_cast<CZSealBody *>(m_entity);
	CAiState* state = const_cast<const CSealCtrlAi *>(this)->GetAiState();

	if ((state != NULL ? state->m_state : 0) == STATE_SUSPENDED)
	{
		StateTick(dT);

		if ((!m_snoozing && !m_sleeping) || !aiEnabled)
			return false;
	}

	if (!seal->m_isAlive)
		return true;

	if (!(!m_snoozing && !m_sleeping))
	{
		aiSleepingCount += m_sleeping ? 1 : 0;
		aiSnoozingCount += m_snoozing ? 1 : 0;
		EventTick(dT);
		return false;
	}

	aiActiveCount++;
	m_lastPos = *seal->GetPosW();
	m_target.Tick(seal, dT);
	seal->InvalidateFollowParams();
	UpdateViewCone();
	m_creeping = 0;
	state = const_cast<const CSealCtrlAi *>(this)->GetAiState();

	if ((state != NULL ? state->m_state : 0) != STATE_SURRENDER)
		SensorPreTick(dT);

	StateTick(dT);

	switch (m_mode)
	{
	case AIM_IDLE:
		IdleTick(dT);
		break;
	case AIM_HOLD:
		if (m_throttle[2] != 0.0f)
			Output("spinner!\n");

		break;
	case AIM_PATH:
		PathFollowTick(dT);
		break;
	case AIM_CREEP:
		CreepTick(dT);
		break;
	case AIM_SLIDE:
		SlideTick(dT);
		break;
	case AIM_FOLLOW:
		FollowTick(dT);
		break;
	default:
		break;
	}

	m_modeTimer += dT;

	for (s32 i = 0; i < 3; i++)
	{
		f32 goal = m_throttle_goal[i];
		f32 delta = goal - m_throttle[i];

		if (delta == 0.0f)
			continue;

		f32 rate = (fabsf(goal) <= fabsf(m_throttle[i]) ? decelRate[i] : accelRate[i]) * dT;
		f32 step = delta < 0.0f ? -rate : rate;

		if (!(fabsf(step) <= fabsf(delta)))
			step = delta;

		m_throttle[i] += step;

		if (_close_enough<f32>(m_throttle[i], m_throttle_goal[i], throttleEps))
			m_throttle[i] = m_throttle_goal[i];
	}

	CValve* shotat = m_valve[1];
	u32 value = shotat->m_value;
	u32 next = value != 0 ? value - 1 : 0;
	shotat->m_value = next;

	if (value != next)
		shotat->MakeCallbacks(next != 0 ? (VALVE_STATE)1 : (VALVE_STATE)2);

	return true;
}

/* @socom-skeleton stub OnRecycleEntity__11CSealCtrlAiFP7CEntity */
void CSealCtrlAi::OnRecycleEntity(CEntity *entity)
{
	/* 0x267590 (CEntity::DoRecycleEntity): this AI's own body is recycled - it leaves its
	 * unit, and the mission ends for it */
	if (m_entity != entity)
		return;

	if (m_unit != NULL)
		CSealUnit::SealLeaveUnit(static_cast<CZSealBody *>(m_entity));

	OnMissionEnd();
}

