	CPnt3D* pos = seal->GetPosW();
	CPnt3D point;

	if (fp.m_flags & 2)
		CAi::LeadTargetG(pos, &seal->m_velW, fp.m_weapon->GetMuzzleVelocity(), &fp.m_targetPos, &fp.m_targetVel, &point);
	else
		point = fp.m_targetPos;

