	dir.Scale(vx, &dir);
	f32 power = dist / reach;
	dir.y = vy;
	fp.m_throwVec = dir;
	f32 low = dyn->m_throw_params.m_abort_threshold;
	fp.m_throwPower = low < power ? power : low;
	fp.m_aimDirM = CPnt3D::unit_nz;
	fp.m_stance = 0;
	fp.m_flags |= 0x7080000u;
